        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) { // k even and r == k/2
