            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n || edges == null) {
        return 0;
    }
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length < 2) continue;
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    boolean[] visited = new boolean[n];
    int[] time = new int[1];
    dfs(0, graph, hasApple, visited, time);
    return time[0];
}

private boolean dfs(int node, java.util.List<Integer>[] graph, boolean[] hasApple, boolean[] visited, int[] time) {
    visited[node] = true;
    boolean hasAppleInSubtree = hasApple[node];
    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            boolean childHasApple = dfs(neighbor, graph, hasApple, visited, time);
            if (childHasApple) {
                time[0] += 2;
                hasAppleInSubtree = true;
            }
        }
    }
    return hasAppleInSubtree;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    // Frequency array for lowercase English letters
    int[] freq = new int[26];
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("Input string must contain only lowercase letters a-z");
        }
        freq[c - 'a']++;
    }

    StringBuilder result = new StringBuilder(n);
    while (result.length() < n) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    dp[0] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int i = 0; i < n; i++) {
        int num = nums[i];
        int maxK = Math.min(i + 1, n - 1); // we don't need subsets of size n
        for (int k = maxK; k >= 1; k--) {
            if (dp[k - 1] == null) continue;
            if (dp[k] == null) dp[k] = new java.util.HashSet<>();
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((long) totalSum * k % n != 0) continue;
        int target = (int) ((long) totalSum * k / n);
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        // If there are no steps or only one step, we can start at the top directly.
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i.
    // We only need the last two values to compute the next one.
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    // Mapping of letters a-z to Morse code
    final String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    if (words == null || words.length == 0) {
        return 0;
    }

    try {
        java.util.Set<String> uniqueSet = new java.util.HashSet<>();
        for (String word : words) {
            if (word == null) {
                continue; // skip null words
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < word.length(); i++) {
                char c = word.charAt(i);
                if (c >= 'a' && c <= 'z') {
                    sb.append(morse[c - 'a']);
                } else if (c >= 'A' && c <= 'Z') {
                    sb.append(morse[c - 'A']);
                } // ignore non-alphabetic characters
            }
            uniqueSet.add(sb.toString());
        }
        return uniqueSet.size();
    } catch (Exception e) {
        // In case of unexpected errors, return 0
        return 0;
    }
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (total > Integer.MAX_VALUE) {
        return false; // k too large to handle
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

