private void dfs(String s, int index, java.util.Set<String> used, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, i + 1, used, count + 1, max);
            used.remove(sub);
        }
    }
}

