        } else {
            // any other string is considered a folder entry
            // we only increment depth if it looks like a folder path
            if (log.endsWith("/")) {
                depth++;
            }
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: each character contributes at least 1 and at most 26.
    if (n <= 0 || k <= 0 || k < n || k > 26L * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        // Try the smallest possible value for this position.
        for (int val = 1; val <= 26; val++) {
            int remainingSum = k - val;
            // Check if the remaining sum can be distributed among the remaining positions.
            if (remainingSum >= remainingPositions && remainingSum <= 26L * remainingPositions) {
                sb.append((char) ('a' + val - 1));
                k = remainingSum;
                break;
            }
        }
    }
    return sb.toString();
}

