public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result; // no non‑negative stepping numbers
    }
    if (low < 0) {
        low = 0;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        if (current > high / 10) {
            continue; // further expansion would exceed high
        }
        int lastDigit = (int) (current % 10);
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    // Handle null or empty matrix
    if (mat == null || mat.length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = 0;
    // Find the first non‑null row to determine column count
    for (int i = 0; i < m; i++) {
        if (mat[i] != null) {
            n = mat[i].length;
            break;
        }
    }
    if (n == 0) {
        return 0;
    }

    // DP arrays for four directions
    int[][] dpH = new int[m][n];   // horizontal
    int[][] dpV = new int[m][n];   // vertical
    int[][] dpD = new int[m][n];   // main diagonal
    int[][] dpAD = new int[m][n];  // anti‑diagonal

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        // Skip null rows
        if (mat[i] == null) {
            continue;
        }
        // If a row has a different length, treat missing cells as 0
        int rowLen = mat[i].length;
        for (int j = 0; j < n; j++) {
            int val = (j < rowLen) ? mat[i][j] : 0;
            if (val == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;

                int localMax = Math.max(
                        Math.max(dpH[i][j], dpV[i][j]),
                        Math.max(dpD[i][j], dpAD[i][j])
                );
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle negative numbers and Integer.MIN_VALUE safely
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);
    String digits = Long.toString(absValue);

    StringBuilder result = new StringBuilder();
    int len = digits.length();

    // Determine the size of the first group (may be less than 3)
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    // Append the first group
    result.append(digits.substring(0, firstGroup));

    // Append remaining groups with dot separators
    for (int i = firstGroup; i < len; i += 3) {
        result.append('.');
        result.append(digits.substring(i, i + 3));
    }

    // Prepend negative sign if needed
    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

